// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 warpTo, uint256 unlockParam, address actor, uint128 amount) public {
        vm.assume(actor != address(0));
        warpTo = bound(warpTo, 1, type(uint256).max / 2);
        amount = uint128(bound(uint256(amount), 0, type(uint128).max));
        vm.warp(warpTo);
        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.Put{value: uint256(amount)}(unlockParam);
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= warpTo);
    }
}
